"""Install managed skill files without overwriting unrecognized local changes."""
import argparse
import datetime
import hashlib
import json
import os
from pathlib import Path
import shutil
import tempfile

ROOT = Path(__file__).resolve().parents[1]
SKILLS = ('jeb-import', 'jeb-query')
# Generated by `jeb setup` inside the installed skill; removed on uninstall.
GENERATED = ('skills/jeb-import/scripts/venv', 'skills/jeb-import/scripts/.venv.lock',
             'skills/jeb-import/scripts/__pycache__', 'skills/jeb-query/scripts/__pycache__')


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def executable(name):
    return name.endswith('/jeb') or name.endswith('.sh')


def load_manifest(config):
    manifest_path = config / 'skills/.jeb-install.json'
    if manifest_path.is_symlink():
        raise ValueError('Refusing a symlink installation manifest.')
    old = json.loads(manifest_path.read_text()) if manifest_path.exists() else {}
    if not isinstance(old, dict):
        raise ValueError('Installation manifest must be an object; preserve it for review.')
    return manifest_path, old


def source_files():
    sources = {}
    for skill in SKILLS:
        source = ROOT / skill
        for required in ('SKILL.md', 'jeb'):
            if not (source / required).is_file():
                raise ValueError(f'Incomplete source checkout, missing {source / required}')
            sources[f'skills/{skill}/{required}'] = source / required
        for folder in ('scripts', 'references'):
            if not (source / folder).is_dir():
                continue
            for path in sorted((source / folder).iterdir()):
                if path.is_file() and not path.name.startswith('.'):
                    sources[f'skills/{skill}/{folder}/{path.name}'] = path
    sources['agents/J.E.B.E.D.I.A.H..md'] = ROOT / 'agent/J.E.B.E.D.I.A.H..md'
    return sources


def checked(config, name):
    target = config / name
    # Do not follow directory symlinks into another checkout or installation.
    if any(parent.is_symlink() for parent in (target, *target.parents)):
        raise ValueError(f'Refusing symlink installation path: {target}')
    if target.exists() and not target.is_file():
        raise ValueError(f'Expected a file: {target}')
    return target


def write_manifest(manifest_path, entries):
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(mode='w', dir=manifest_path.parent, delete=False) as handle:
        staging = Path(handle.name)
        json.dump(entries, handle, indent=2)
    try:
        os.replace(staging, manifest_path)
    finally:
        staging.unlink(missing_ok=True)


class Transaction:
    """File changes that are undone, in reverse, if a later step fails."""

    def __init__(self):
        self.stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
        self.undo, self.backups = [], []

    def back_up(self, target):
        backup = target.with_name(target.name + '.backup-' + self.stamp)
        if backup.exists():
            raise ValueError(f'Backup already exists: {backup}')
        target.rename(backup)
        self.undo.append(lambda: backup.rename(target))
        self.backups.append(backup)

    def remember(self, target):
        if target.exists():
            data, mode = target.read_bytes(), target.stat().st_mode

            def restore():
                target.write_bytes(data)
                target.chmod(mode)
        else:
            def restore():
                target.unlink(missing_ok=True)
        self.undo.append(restore)

    def copy(self, source, target, mode=None):
        target.parent.mkdir(parents=True, exist_ok=True)
        self.remember(target)
        with tempfile.NamedTemporaryFile(dir=target.parent, delete=False) as handle:
            staging = Path(handle.name)
        try:
            shutil.copy2(source, staging)
            if mode is not None:
                staging.chmod(mode)
            os.replace(staging, target)
        finally:
            staging.unlink(missing_ok=True)

    def remove(self, target):
        self.remember(target)
        target.unlink()

    def rollback(self):
        for step in reversed(self.undo):
            step()


def install(config, force=False, dry_run=False):
    config = config.expanduser().absolute()
    manifest_path, old = load_manifest(config)
    sources = source_files()
    operations, conflicts = [], []
    for name, source in sources.items():
        target = checked(config, name)
        if target.exists() and digest(target) == digest(source):
            if executable(name) and not os.access(target, os.X_OK):
                operations.append((name, source, target))
            continue
        if target.exists() and old.get(name) != digest(target):
            conflicts.append(target)
        operations.append((name, source, target))
    # Files a previous version installed that this version no longer ships.
    stale = []
    for name in sorted(set(old) - set(sources)):
        target = checked(config, name)
        if target.exists():
            (stale if digest(target) == old[name] else conflicts).append(target)
    legacy = config / 'agents/jebediah.md'
    if legacy.is_dir() and not legacy.is_symlink():
        raise ValueError(f'Expected an agent file, not a directory: {legacy}')
    if legacy.exists() or legacy.is_symlink():
        conflicts.append(legacy)
    if conflicts and not force:
        raise ValueError('Conflicting files (use --force to back up): ' + ', '.join(map(str, conflicts)))
    if dry_run:
        for _, _, target in operations:
            print(f'Would install: {target}')
        for target in stale:
            print(f'Would remove (no longer shipped): {target}')
        for target in conflicts:
            print(f'Would back up: {target}')
        print(f'Dry run: {len(operations)} to install, {len(stale)} to remove, {len(conflicts)} to back up.')
        return
    change = Transaction()
    try:
        for target in conflicts:
            change.back_up(target)
        for name, source, target in operations:
            change.copy(source, target, 0o755 if executable(name) else None)
        for target in stale:
            change.remove(target)
        write_manifest(manifest_path, {name: digest(path) for name, path in sources.items()})
    except Exception:
        change.rollback()
        raise
    print(f'Installed jeb-import, jeb-query and the primary agent into {config}')
    print('No OpenCode configuration or plugin registration was changed.')
    for target in stale:
        print(f'Removed (no longer shipped): {target}')
    for backup in change.backups:
        print(f'Backup: {backup}')
    print(f'Next: "{config}/skills/jeb-import/jeb" setup [--viz]')


def uninstall(config, dry_run=False):
    """Remove managed files; edited ones are kept as backups. Engagement
    databases live in project directories and are never touched."""
    config = config.expanduser().absolute()
    manifest_path, old = load_manifest(config)
    if not old:
        raise ValueError(f'No JEB installation manifest at {manifest_path}; nothing to uninstall.')
    removed, edited = [], []
    for name in sorted(old):
        target = checked(config, name)
        if target.exists():
            (removed if digest(target) == old[name] else edited).append(target)
    generated = [config / name for name in GENERATED if (config / name).exists()]
    if dry_run:
        for target in removed + generated:
            print(f'Would remove: {target}')
        for target in edited:
            print(f'Would back up (locally edited): {target}')
        return
    change = Transaction()
    try:
        for target in edited:
            change.back_up(target)
        for target in removed:
            change.remove(target)
    except Exception:
        change.rollback()
        raise
    for target in generated:
        if target.is_dir() and not target.is_symlink():
            shutil.rmtree(target)
        else:
            target.unlink()
    manifest_path.unlink()
    # Directories left empty by the removal, deepest first; never the config root.
    for skill in SKILLS:
        root = config / 'skills' / skill
        if root.is_dir() and not root.is_symlink():
            for folder in sorted((p for p in root.rglob('*') if p.is_dir()), reverse=True) + [root]:
                if not any(folder.iterdir()):
                    folder.rmdir()
    print(f'Uninstalled jeb-import, jeb-query and the primary agent from {config}')
    for backup in change.backups:
        print(f'Kept locally edited file as: {backup}')
    print('Project databases (<project>/chroma_db) were not touched.')


def main():
    parser = argparse.ArgumentParser(
        prog='install-skills.sh', description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog='Installs the jeb-import and jeb-query skills and the J.E.B.E.D.I.A.H. agent into\n'
               '$OPENCODE_CONFIG_DIR, else ${XDG_CONFIG_HOME:-~/.config}/opencode. Nothing else\n'
               'is changed. Afterwards run: <config>/skills/jeb-import/jeb setup [--viz]')
    parser.add_argument('--force', action='store_true', help='Back up conflicting or locally edited files before replacement')
    parser.add_argument('--uninstall', action='store_true', help='Remove the installed skills, agent and their Python environment')
    parser.add_argument('--dry-run', action='store_true', help='Show what would change without changing anything')
    args = parser.parse_args()
    config = Path(os.environ.get('OPENCODE_CONFIG_DIR') or
                  str(Path(os.environ.get('XDG_CONFIG_HOME') or Path.home() / '.config') / 'opencode'))
    try:
        if args.uninstall:
            if args.force:
                parser.error('--force does not apply to --uninstall; edited files are always kept as backups.')
            uninstall(config, args.dry_run)
        else:
            install(config, args.force, args.dry_run)
    except (ValueError, OSError) as exc:
        parser.exit(1, f'{"Uninstall" if args.uninstall else "Installation"} failed: {exc}\n')


if __name__ == '__main__':
    main()
